(function($){'use strict';function getCookie(name){var match=document.cookie.match(new RegExp('(?:^|; )'+name+'=([^;]*)'));return match?match[1]:null}
function loadVisited(cookieKey){var raw=getCookie(cookieKey);if(!raw)return{};try{return JSON.parse(decodeURIComponent(raw))}catch(e){return{}}}
function getVisitedPages(pages,visited){return pages.filter(function(p){return!!visited[p.id]})}
function getRecommendedIndex(pages,visited){for(var i=0;i<pages.length;i++){if(!visited[pages[i].id])return i}
return-1}
$(document).ready(function(){var sc=window.JG_SC;if(!sc||!sc.pages||!sc.pages.length)return;var pages=sc.pages;var visited=loadVisited(sc.cookie_key);var total=pages.length;if($('#jg-continue-grid').length){hydrateGrid(pages,visited)}
if($('#jg-guided-tour').length){hydrateGuidedTour(pages,visited,total)}});function hydrateGrid(pages,visited){var recommendedIdx=getRecommendedIndex(pages,visited);$('#jg-continue-grid .jg-sc-card').each(function(){var $card=$(this);var pid=parseInt($card.data('pid'),10);var index=parseInt($card.data('index'),10);var $bubble=$card.find('.jg-sc-bubble');var $meta=$card.find('.jg-sc-card-meta');var $badge=$card.find('.jg-sc-next-badge');if(visited[pid]){$card.addClass('jg-sc-visited');$bubble.removeClass('jg-sc-unvisited').addClass('jg-sc-visited-bubble').html('<img src="/wp-content/uploads/2026/06/Frame-2147227796.svg" alt="Visited" class="jg-sc-bubble-icon">');$meta.text('✓ Visited')}else if(index===recommendedIdx){$card.addClass('jg-sc-recommended');$meta.text('+ Recommended next step');$badge.show()}})}
function hydrateGuidedTour(pages,visited,total){var visitedPages=getVisitedPages(pages,visited);var visitedCount=visitedPages.length;var recIdx=getRecommendedIndex(pages,visited);$('#jg-guided-tour').show();var tourUrl=pages[0]?pages[0].url:'#';var progressPct=total?Math.round((visitedCount/total)*100):0;if(visitedCount>1){buildMultiPanel(pages,visitedPages,visitedCount,total,recIdx,progressPct,tourUrl)}else if(visitedCount===1){buildSinglePanel(pages,visitedPages,total,recIdx,progressPct,tourUrl)}else{buildNonePanel(pages,tourUrl)}}
function getLastVisited(visitedPages,pages){return visitedPages[visitedPages.length-1]}
function getImg(page){return page&&page.thumb?page.thumb:''}
function pageIndex(pages,pid){for(var i=0;i<pages.length;i++){if(parseInt(pages[i].id,10)===parseInt(pid,10))return i}
return-1}
function visitedListItem(page,idx){var $link=$('<a class="jg-gvi-link">').attr('href',page.url).attr('title','Go back to '+page.label).append($('<span class="jg-gvi-num">').text(idx+1)).append($('<span class="jg-gvi-label">').text(page.label));return $('<li>').append($link)}
function fillNextSection($panel,pages,nextPage){if(nextPage){var nextIdx=pageIndex(pages,nextPage.id);$panel.find('.jg-guided-next-primary').attr('href',nextPage.url).attr('data-num',nextIdx+1).html('<span class="jg-gvi-num">'+(nextIdx+1)+'</span><span>'+nextPage.label+'</span>');return}
var $heading=$panel.find('.jg-guided-next-heading');$heading.text($heading.attr('data-complete-text')||'Journey Completed');$panel.find('.jg-guided-next-item').hide();$panel.find('.jg-guided-complete-item').show()}
function buildMultiPanel(pages,visitedPages,visitedCount,total,recIdx,progressPct,tourUrl){var $panel=$('#jg-guided-multi');var lastTwo=visitedPages.slice(-2);var current=getLastVisited(visitedPages,pages);var nextPage=recIdx>=0?pages[recIdx]:null;$panel.find('.jg-gv-bar-fill').css('width',progressPct+'%');var $list=$panel.find('.jg-guided-visited-items').empty();lastTwo.forEach(function(p){$list.append(visitedListItem(p,pageIndex(pages,p.id)))});var img=getImg(current);if(img)$panel.find('.jg-guided-current-img').attr('src',img);$panel.find('.jg-guided-current-label').text(current?current.label:'');fillNextSection($panel,pages,nextPage);$panel.find('.jg-guided-view-full').attr('href',tourUrl);$panel.show()}
function buildSinglePanel(pages,visitedPages,total,recIdx,progressPct,tourUrl){var $panel=$('#jg-guided-single');var current=visitedPages[0];var nextPage=recIdx>=0?pages[recIdx]:null;$panel.find('.jg-gv-bar-fill').css('width',progressPct+'%');var $list=$panel.find('.jg-guided-visited-items').empty();$list.append(visitedListItem(current,pageIndex(pages,current.id)));$panel.find('.jg-guided-count-label').text(total+' Page Guided Tour');var img=getImg(current);if(img)$panel.find('.jg-guided-current-img').attr('src',img);$panel.find('.jg-guided-current-label').text(current.label);fillNextSection($panel,pages,nextPage);$panel.find('.jg-guided-view-full').attr('href',tourUrl);$panel.show()}
function buildNonePanel(pages,tourUrl){var $panel=$('#jg-guided-none');var p1=pages[0]||null;var p2=pages[1]||null;if(p1){$panel.find('.jg-guided-none-p1').attr('href',p1.url).attr('data-num',1).html('<span class="jg-gvi-num">1</span><span>'+p1.label+'</span>')}
if(p2){$panel.find('.jg-guided-none-p2').attr('href',p2.url).attr('data-num',2).html('<span class="jg-gvi-num">2</span><span>'+p2.label+'</span>')}
var img=p1&&p1.thumb?p1.thumb:'';if(img)$panel.find('.jg-guided-img').attr('src',img);$panel.find('.jg-guided-view-full').attr('href',tourUrl);$panel.show()}})(jQuery)